101	 *
102	 * | Method | Path                          | Description                                             |
103	 * |--------|-------------------------------|---------------------------------------------------------|
104	 * | GET    | /api/config/notes-display     | Return current `notesCardHeight` and `notesColumns`     |
105	 * | PUT    | /api/config/notes-display     | Update notes display settings (partial updates allowed) |
106	 *
107	 * Changes take effect immediately (the in-memory `appConfig` is mutated) and
108	 * are persisted to `config.json` via `saveConfigField()`.
109	 *
110	 * **Security:** tokens are never returned in full — only the last 4 characters
111	 * are exposed. The `host` field is validated against an injection-safe pattern.
112	 *
113	 * @param options - Named-options bag: `router`, `appConfig`, optional
114	 *   `configPath` (defaults to tool-root `config.json`), optional
115	 *   `pollingManager` (restarts polling loop when present).
116	 */
117	export function registerConfigRoutes(options: ConfigRoutesOptions): void {
118	    const { router, appConfig, configPath, pollingManager } = options;
119	    // ------------------------------------------------------------------
120	    // GET /api/config/credentials — list all (tokens masked)
121	    // ------------------------------------------------------------------
122	    router.get('/api/config/credentials', (
123	        _req: IncomingMessage,
124	        res: ServerResponse,
125	        _params: Record<string, string>,
126	    ): void => {
127	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
128	    });
129	
130	    // ------------------------------------------------------------------
131	    // PUT /api/config/credentials — add or update a single entry
132	    // ------------------------------------------------------------------
133	    router.put('/api/config/credentials', async (
134	        req: IncomingMessage,
135	        res: ServerResponse,
136	        _params: Record<string, string>,
137	    ): Promise<void> => {
138	        let body: unknown;
139	        try {
140	            body = await parseJsonBody(req);
141	        } catch (err) {
142	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
143	            return;
144	        }
145	
146	        if (!isPlainObject(body)) {
147	            sendError(res, 400, 'Request body must be a JSON object.');
148	            return;
149	        }
150	
151	        const { host, token } = body as { host?: unknown; token?: unknown };
152	
153	        if (typeof host !== 'string' || host.trim() === '') {
154	            sendError(res, 400, 'Missing or invalid field "host": must be a non-empty string.');
155	            return;
156	        }
157	
158	        if (typeof token !== 'string' || token.trim() === '') {
159	            sendError(res, 400, 'Missing or invalid field "token": must be a non-empty string.');
160	            return;
161	        }
162	
163	        const cleanHost = host.trim();
164	
165	        // Security: reject hosts with path separators or whitespace to prevent
166	        // key injection that could interfere with URL credential injection.
167	        if (/[\s/\\]/.test(cleanHost)) {
168	            sendError(res, 400, 'Field "host" must not contain path separators or whitespace.');
169	            return;
170	        }
171	
172	        // Defence-in-depth: reject prototype-pollution keys.
173	        if (['__proto__', 'constructor', 'prototype'].includes(cleanHost)) {
174	            sendError(res, 400, 'Field "host" contains a reserved name.');
175	            return;
176	        }
177	
178	        const cleanToken = token.trim();
179	
180	        // Update in-memory config.
181	        if (!appConfig.gitCredentials) {
182	            appConfig.gitCredentials = {};
183	        }
184	        appConfig.gitCredentials[cleanHost] = cleanToken;
185	
186	        // Persist to disk.
187	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
188	
189	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
190	    });
191	
192	    // ------------------------------------------------------------------
193	    // DELETE /api/config/credentials/:host — remove a single entry
194	    // Sync handler (no request body to parse — unlike the async PUT above).
195	    // ------------------------------------------------------------------
196	    router.delete('/api/config/credentials/:host', (
197	        _req: IncomingMessage,
198	        res: ServerResponse,
199	        params: Record<string, string>,
200	    ): void => {
201	        let host: string;
202	        try {
203	            host = decodeURIComponent(params['host']);
204	        } catch {
205	            sendError(res, 400, 'Malformed host parameter.');
206	            return;
207	        }
208	
209	        if (!appConfig.gitCredentials || !(host in appConfig.gitCredentials)) {
210	            sendError(res, 404, `No credential entry found for host "${host}".`);
211	            return;
212	        }
213	
214	        delete appConfig.gitCredentials[host];
215	
216	        // When the map is empty, remove the field entirely (undefined removes
217	        // it from config.json via saveConfigField).
218	        const isEmpty = Object.keys(appConfig.gitCredentials).length === 0;
219	        if (isEmpty) {
220	            appConfig.gitCredentials = undefined;
221	        }
222	
223	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
224	
225	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
226	    });
227	
228	    // ------------------------------------------------------------------
229	    // GET /api/config/polling — return the current polling interval
230	    // ------------------------------------------------------------------
231	    router.get('/api/config/polling', (
232	        _req: IncomingMessage,
233	        res: ServerResponse,
234	        _params: Record<string, string>,
235	    ): void => {
236	        sendJson(res, 200, {
237	            gitPollingIntervalSeconds: appConfig.gitPollingIntervalSeconds,
238	        });
239	    });
240	
241	    // ------------------------------------------------------------------
242	    // PUT /api/config/polling — update the polling interval
243	    // Validates: must be a finite integer >= 10.
244	    // ------------------------------------------------------------------
245	    router.put('/api/config/polling', async (
246	        req: IncomingMessage,
247	        res: ServerResponse,
248	        _params: Record<string, string>,
249	    ): Promise<void> => {
250	        let body: unknown;

251	        try {
252	            body = await parseJsonBody(req);
253	        } catch (err) {
254	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
255	            return;
256	        }
257	
258	        if (!isPlainObject(body)) {
259	            sendError(res, 400, 'Request body must be a JSON object.');
260	            return;
261	        }
262	
263	        const { seconds } = body as { seconds?: unknown };
264	
265	        if (typeof seconds !== 'number') {
266	            sendError(res, 400, 'Missing or invalid field "seconds": must be a number.');
267	            return;
268	        }
269	
270	        if (!Number.isFinite(seconds) || !Number.isInteger(seconds)) {
271	            sendError(res, 400, 'Field "seconds" must be a finite integer.');
272	            return;
273	        }
274	
275	        if (seconds < MIN_POLLING_INTERVAL_SECONDS) {
276	            sendError(
277	                res,
278	                400,
279	                `Field "seconds" must be at least ${MIN_POLLING_INTERVAL_SECONDS}. Received: ${seconds}.`,
280	            );
281	            return;
282	        }
283	
284	        if (seconds > MAX_POLLING_INTERVAL_SECONDS) {
285	            sendError(
286	                res,
287	                400,
288	                `Field "seconds" must be at most ${MAX_POLLING_INTERVAL_SECONDS} (24 hours). Received: ${seconds}.`,
289	            );
290	            return;
291	        }
292	
293	        // Update in-memory config.
294	        appConfig.gitPollingIntervalSeconds = seconds;
295	
296	        // Persist to disk.
297	        saveConfigField('gitPollingIntervalSeconds', seconds, configPath);
298	
299	        // Restart the polling loop with the new interval (if a manager was provided).
300	        if (pollingManager !== undefined) {
301	            pollingManager.restart(seconds);
302	        }
303	
304	        sendJson(res, 200, { gitPollingIntervalSeconds: appConfig.gitPollingIntervalSeconds });
305	    });
306	
307	    // ------------------------------------------------------------------
308	    // GET /api/config/webserver-url — return the current webserver URL
309	    // ------------------------------------------------------------------
310	    router.get('/api/config/webserver-url', (
311	        _req: IncomingMessage,
312	        res: ServerResponse,
313	        _params: Record<string, string>,
314	    ): void => {
315	        sendJson(res, 200, { webserverUrl: appConfig.webserverUrl ?? null });
316	    });
317	
318	    // ------------------------------------------------------------------
319	    // PUT /api/config/webserver-url — update the webserver URL
320	    // ------------------------------------------------------------------
321	    router.put('/api/config/webserver-url', async (
322	        req: IncomingMessage,
323	        res: ServerResponse,
324	        _params: Record<string, string>,
325	    ): Promise<void> => {
326	        let body: unknown;
327	        try {
328	            body = await parseJsonBody(req);
329	        } catch (err) {
330	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
331	            return;
332	        }
333	
334	        if (!isPlainObject(body)) {
335	            sendError(res, 400, 'Request body must be a JSON object.');
336	            return;
337	        }
338	
339	        const { url } = body as { url?: unknown };
340	
341	        if (typeof url !== 'string') {
342	            sendError(res, 400, 'Missing or invalid field "url": must be a string.');
343	            return;
344	        }
345	
346	        const trimmed = url.trim();
347	
348	        if (trimmed !== '') {
349	            // Defence-in-depth: reject dangerous URL schemes.
350	            const scheme = extractScheme(trimmed);
351	            if (['javascript', 'data', 'vbscript'].includes(scheme)) {
352	                sendError(res, 400, `URL scheme "${scheme}:" is not permitted.`);
353	                return;
354	            }
355	        }
356	
357	        // Strip trailing slashes to prevent double-slash in constructed URLs.
358	        const cleanUrl = trimmed !== '' ? trimmed.replace(/\/+$/, '') : undefined;
359	
360	        // Update in-memory config.
361	        appConfig.webserverUrl = cleanUrl;
362	
363	        // Persist to disk.
