385	    // Accepts partial updates: only provided fields are modified.
386	    // Validates: notesCardHeight ∈ [MIN_NOTES_CARD_HEIGHT, MAX_NOTES_CARD_HEIGHT]
387	    //            notesColumns    ∈ [MIN_NOTES_COLUMNS,    MAX_NOTES_COLUMNS]
388	    // ------------------------------------------------------------------
389	    router.put('/api/config/notes-display', async (
390	        req: IncomingMessage,
391	        res: ServerResponse,
392	        _params: Record<string, string>,
393	    ): Promise<void> => {
394	        let body: unknown;
395	        try {
396	            body = await parseJsonBody(req);
397	        } catch (err) {
398	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
399	            return;
400	        }
401	
402	        if (!isPlainObject(body)) {
403	            sendError(res, 400, 'Request body must be a JSON object.');
404	            return;
405	        }
406	
407	        const { notesCardHeight, notesColumns } = body as {
408	            notesCardHeight?: unknown;
409	            notesColumns?: unknown;
410	        };
411	
412	        // Validate notesCardHeight if provided.
413	        if (notesCardHeight !== undefined) {
414	            if (typeof notesCardHeight !== 'number') {
415	                sendError(res, 400, 'Field "notesCardHeight" must be a number.');
416	                return;
417	            }
418	            if (!Number.isFinite(notesCardHeight) || !Number.isInteger(notesCardHeight)) {
419	                sendError(res, 400, 'Field "notesCardHeight" must be a finite integer.');
