426	                    `Field "notesCardHeight" must be at least ${MIN_NOTES_CARD_HEIGHT}. Received: ${notesCardHeight}.`,
427	                );
428	                return;
429	            }
430	            if (notesCardHeight > MAX_NOTES_CARD_HEIGHT) {
431	                sendError(
432	                    res,
433	                    400,
434	                    `Field "notesCardHeight" must be at most ${MAX_NOTES_CARD_HEIGHT}. Received: ${notesCardHeight}.`,
435	                );
436	                return;
437	            }
438	        }
439	
440	        // Validate notesColumns if provided.
441	        if (notesColumns !== undefined) {
442	            if (typeof notesColumns !== 'number') {
443	                sendError(res, 400, 'Field "notesColumns" must be a number.');
444	                return;
445	            }
446	            if (!Number.isFinite(notesColumns) || !Number.isInteger(notesColumns)) {
447	                sendError(res, 400, 'Field "notesColumns" must be a finite integer.');
448	                return;
449	            }
450	            if (notesColumns < MIN_NOTES_COLUMNS) {

451	                sendError(
